//go:build amd64 && !purego

#include "textflag.h"

// func vistrutah256EncryptBlockAsm(dst, src, key *[32]byte, rounds int)
TEXT ·vistrutah256EncryptBlockAsm(SB),NOSPLIT,$0-32
	MOVQ dst+0(FP), DI
	MOVQ src+8(FP), SI
	MOVQ key+16(FP), DX
	MOVQ rounds+24(FP), CX
	MOVOU 0(SI), X0
	MOVOU 16(SI), X1
	MOVOU 0(DX), X2
	MOVOU 16(DX), X3
	MOVOA X3, X4
	MOVOA X2, X5
	PXOR X6, X6
	MOVOU ·vistrutahConsts+0(SB), X7
	MOVOU ·vistrutahConsts+16(SB), X8
	MOVOU ·vistrutahConsts+64(SB), X9
	PXOR X4, X0
	PXOR X5, X1
	AESENC X2, X0
	AESENC X3, X1
	AESENC X6, X0
	AESENC X6, X1
	PSHUFB X9, X0
	PSHUFB X9, X1
	MOVOA X0, X10
	PUNPCKLQDQ X1, X0
	PUNPCKHQDQ X1, X10
	MOVOA X10, X1
	PSHUFB X7, X4
	PSHUFB X8, X5
	MOVOU ·vistrutahRoundConstants+0(SB), X10
	PXOR X4, X0
	PXOR X10, X0
	PXOR X5, X1
	AESENC X2, X0
	AESENC X3, X1
	AESENC X6, X0
	AESENC X6, X1
	PSHUFB X9, X0
	PSHUFB X9, X1
	MOVOA X0, X10
	PUNPCKLQDQ X1, X0
	PUNPCKHQDQ X1, X10
	MOVOA X10, X1
	PSHUFB X7, X4
	PSHUFB X8, X5
	MOVOU ·vistrutahRoundConstants+16(SB), X10
	PXOR X4, X0
	PXOR X10, X0
	PXOR X5, X1
	AESENC X2, X0
	AESENC X3, X1
	AESENC X6, X0
	AESENC X6, X1
	PSHUFB X9, X0
	PSHUFB X9, X1
	MOVOA X0, X10
	PUNPCKLQDQ X1, X0
	PUNPCKHQDQ X1, X10
	MOVOA X10, X1
	PSHUFB X7, X4
	PSHUFB X8, X5
	MOVOU ·vistrutahRoundConstants+32(SB), X10
	PXOR X4, X0
	PXOR X10, X0
	PXOR X5, X1
	AESENC X2, X0
	AESENC X3, X1
	AESENC X6, X0
	AESENC X6, X1
	PSHUFB X9, X0
	PSHUFB X9, X1
	MOVOA X0, X10
	PUNPCKLQDQ X1, X0
	PUNPCKHQDQ X1, X10
	MOVOA X10, X1
	PSHUFB X7, X4
	PSHUFB X8, X5
	MOVOU ·vistrutahRoundConstants+48(SB), X10
	PXOR X4, X0
	PXOR X10, X0
	PXOR X5, X1
	CMPQ CX, $10
	JE v256_blk_aesni_final
	AESENC X2, X0
	AESENC X3, X1
	AESENC X6, X0
	AESENC X6, X1
	PSHUFB X9, X0
	PSHUFB X9, X1
	MOVOA X0, X10
	PUNPCKLQDQ X1, X0
	PUNPCKHQDQ X1, X10
	MOVOA X10, X1
	PSHUFB X7, X4
	PSHUFB X8, X5
	MOVOU ·vistrutahRoundConstants+64(SB), X10
	PXOR X4, X0
	PXOR X10, X0
	PXOR X5, X1
	AESENC X2, X0
	AESENC X3, X1
	AESENC X6, X0
	AESENC X6, X1
	PSHUFB X9, X0
	PSHUFB X9, X1
	MOVOA X0, X10
	PUNPCKLQDQ X1, X0
	PUNPCKHQDQ X1, X10
	MOVOA X10, X1
	PSHUFB X7, X4
	PSHUFB X8, X5
	MOVOU ·vistrutahRoundConstants+80(SB), X10
	PXOR X4, X0
	PXOR X10, X0
	PXOR X5, X1
v256_blk_aesni_final:
	AESENC X2, X0
	AESENC X3, X1
	PSHUFB X7, X4
	PSHUFB X8, X5
	AESENCLAST X4, X0
	AESENCLAST X5, X1
	MOVOU X0, 0(DI)
	MOVOU X1, 16(DI)
	PXOR X0, X0
	PXOR X1, X1
	PXOR X2, X2
	PXOR X3, X3
	PXOR X4, X4
	PXOR X5, X5
	PXOR X6, X6
	PXOR X7, X7
	PXOR X8, X8
	PXOR X9, X9
	PXOR X10, X10
	XORQ DI, DI
	XORQ SI, SI
	XORQ DX, DX
	XORQ CX, CX
	RET

// func vistrutah256DecryptBlockAsm(dst, src, key *[32]byte, rounds int)
TEXT ·vistrutah256DecryptBlockAsm(SB),NOSPLIT,$0-32
	MOVQ dst+0(FP), DI
	MOVQ src+8(FP), SI
	MOVQ key+16(FP), DX
	MOVQ rounds+24(FP), CX
	MOVOU 0(SI), X0
	MOVOU 16(SI), X1
	MOVOU 0(DX), X2
	MOVOU 16(DX), X3
	MOVOA X3, X4
	MOVOA X2, X5
	AESIMC X2, X2
	AESIMC X3, X3
	MOVOU ·vistrutahConsts+352(SB), X6
	MOVOU ·vistrutahConsts+368(SB), X7
	PSHUFB X6, X4
	PSHUFB X7, X5
	CMPQ CX, $10
	JE v256_dec_blk_aesni_rk_ready
	MOVOU ·vistrutahConsts+0(SB), X6
	MOVOU ·vistrutahConsts+16(SB), X7
	PSHUFB X6, X4
	PSHUFB X7, X5
	PSHUFB X6, X4
	PSHUFB X7, X5
v256_dec_blk_aesni_rk_ready:
	MOVOU ·vistrutahConsts+288(SB), X6
	MOVOU ·vistrutahConsts+304(SB), X7
	PXOR X4, X0
	PXOR X5, X1
	AESDEC X2, X0
	AESDEC X3, X1
	PSHUFB X6, X4
	PSHUFB X7, X5
	CMPQ CX, $10
	JE v256_dec_blk_aesni_rc3
	MOVOU ·vistrutahRoundConstants+80(SB), X8
	PXOR X4, X8
	AESDECLAST X8, X0
	AESDECLAST X5, X1
	MOVOA X0, X8
	PUNPCKLBW X1, X0
	PUNPCKHBW X1, X8
	MOVOA X8, X1
	AESIMC X0, X0
	AESIMC X1, X1
	AESDEC X2, X0
	AESDEC X3, X1
	PSHUFB X6, X4
	PSHUFB X7, X5
	MOVOU ·vistrutahRoundConstants+64(SB), X8
	PXOR X4, X8
	AESDECLAST X8, X0
	AESDECLAST X5, X1
	MOVOA X0, X8
	PUNPCKLBW X1, X0
	PUNPCKHBW X1, X8
	MOVOA X8, X1
	AESIMC X0, X0
	AESIMC X1, X1
	AESDEC X2, X0
	AESDEC X3, X1
	PSHUFB X6, X4
	PSHUFB X7, X5
v256_dec_blk_aesni_rc3:
	MOVOU ·vistrutahRoundConstants+48(SB), X8
	PXOR X4, X8
	AESDECLAST X8, X0
	AESDECLAST X5, X1
	MOVOA X0, X8
	PUNPCKLBW X1, X0
	PUNPCKHBW X1, X8
	MOVOA X8, X1
	AESIMC X0, X0
	AESIMC X1, X1
	AESDEC X2, X0
	AESDEC X3, X1
	PSHUFB X6, X4
	PSHUFB X7, X5
	MOVOU ·vistrutahRoundConstants+32(SB), X8
	PXOR X4, X8
	AESDECLAST X8, X0
	AESDECLAST X5, X1
	MOVOA X0, X8
	PUNPCKLBW X1, X0
	PUNPCKHBW X1, X8
	MOVOA X8, X1
	AESIMC X0, X0
	AESIMC X1, X1
	AESDEC X2, X0
	AESDEC X3, X1
	PSHUFB X6, X4
	PSHUFB X7, X5
	MOVOU ·vistrutahRoundConstants+16(SB), X8
	PXOR X4, X8
	AESDECLAST X8, X0
	AESDECLAST X5, X1
	MOVOA X0, X8
	PUNPCKLBW X1, X0
	PUNPCKHBW X1, X8
	MOVOA X8, X1
	AESIMC X0, X0
	AESIMC X1, X1
	AESDEC X2, X0
	AESDEC X3, X1
	PSHUFB X6, X4
	PSHUFB X7, X5
	MOVOU ·vistrutahRoundConstants+0(SB), X8
	PXOR X4, X8
	AESDECLAST X8, X0
	AESDECLAST X5, X1
	MOVOA X0, X8
	PUNPCKLBW X1, X0
	PUNPCKHBW X1, X8
	MOVOA X8, X1
	AESIMC X0, X0
	AESIMC X1, X1
	AESDEC X2, X0
	AESDEC X3, X1
	PSHUFB X6, X4
	PSHUFB X7, X5
	AESDECLAST X4, X0
	AESDECLAST X5, X1
	MOVOU X0, 0(DI)
	MOVOU X1, 16(DI)
	PXOR X0, X0
	PXOR X1, X1
	PXOR X2, X2
	PXOR X3, X3
	PXOR X4, X4
	PXOR X5, X5
	PXOR X6, X6
	PXOR X7, X7
	PXOR X8, X8
	XORQ DI, DI
	XORQ SI, SI
	XORQ DX, DX
	XORQ CX, CX
