	VPXOR X5, X1, X1
	VAESENC X2, X0, X0
	VAESENC X3, X1, X1
	VAESENC X6, X0, X0
	VAESENC X6, X1, X1
	VPSHUFB X9, X0, X10
	VPSHUFB X9, X1, X11
	VPUNPCKLQDQ X11, X10, X0
	VPUNPCKHQDQ X11, X10, X1
	VPSHUFB X7, X4, X4
	VPSHUFB X8, X5, X5
	VPXOR ·vistrutahRoundConstants+16(SB), X4, X10
	VPXOR X10, X0, X0
	VPXOR X5, X1, X1
	VAESENC X2, X0, X0
	VAESENC X3, X1, X1
	VAESENC X6, X0, X0
	VAESENC X6, X1, X1
	VPSHUFB X9, X0, X10
	VPSHUFB X9, X1, X11
	VPUNPCKLQDQ X11, X10, X0
	VPUNPCKHQDQ X11, X10, X1
	VPSHUFB X7, X4, X4
	VPSHUFB X8, X5, X5
	VPXOR ·vistrutahRoundConstants+32(SB), X4, X10
	VPXOR X10, X0, X0
	VPXOR X5, X1, X1
	VAESENC X2, X0, X0
	VAESENC X3, X1, X1
	VAESENC X6, X0, X0
	VAESENC X6, X1, X1
	VPSHUFB X9, X0, X10
	VPSHUFB X9, X1, X11
	VPUNPCKLQDQ X11, X10, X0
	VPUNPCKHQDQ X11, X10, X1
	VPSHUFB X7, X4, X4
	VPSHUFB X8, X5, X5
	VPXOR ·vistrutahRoundConstants+48(SB), X4, X10
	VPXOR X10, X0, X0
	VPXOR X5, X1, X1
	CMPQ CX, $10
	JE v256_blk_vex_final
	VAESENC X2, X0, X0
	VAESENC X3, X1, X1
	VAESENC X6, X0, X0
	VAESENC X6, X1, X1
	VPSHUFB X9, X0, X10
	VPSHUFB X9, X1, X11
	VPUNPCKLQDQ X11, X10, X0
	VPUNPCKHQDQ X11, X10, X1
	VPSHUFB X7, X4, X4
	VPSHUFB X8, X5, X5
	VPXOR ·vistrutahRoundConstants+64(SB), X4, X10
	VPXOR X10, X0, X0
	VPXOR X5, X1, X1
	VAESENC X2, X0, X0
	VAESENC X3, X1, X1
	VAESENC X6, X0, X0
	VAESENC X6, X1, X1
	VPSHUFB X9, X0, X10
	VPSHUFB X9, X1, X11
	VPUNPCKLQDQ X11, X10, X0
	VPUNPCKHQDQ X11, X10, X1
	VPSHUFB X7, X4, X4
	VPSHUFB X8, X5, X5
	VPXOR ·vistrutahRoundConstants+80(SB), X4, X10
