// func vistrutah256EncryptBlockYmmAsm(dst, src, key *[32]byte, rounds int)
TEXT ·vistrutah256EncryptBlockYmmAsm(SB),NOSPLIT,$0-32
	MOVQ dst+0(FP), DI
	MOVQ src+8(FP), SI
	MOVQ key+16(FP), DX
	MOVQ rounds+24(FP), CX
	VMOVDQU 0(SI), Y0
	VMOVDQU 0(DX), Y1
	VPERM2I128 $1, Y1, Y1, Y2
	VPXOR X3, X3, X3
	VMOVDQU ·vistrutahConsts+0(SB), Y4
	VMOVDQU ·vistrutahConsts+64(SB), Y5
	VPXOR Y2, Y0, Y0
	VAESENC Y1, Y0, Y0
	VAESENC Y3, Y0, Y0
	VPSHUFB Y5, Y0, Y0
	VPERMQ $216, Y0, Y0
	VPSHUFB Y4, Y2, Y2
	VMOVDQU ·vistrutahRoundConstants+0(SB), X6
	VPXOR Y2, Y0, Y0
	VPXOR Y6, Y0, Y0
	VAESENC Y1, Y0, Y0
	VAESENC Y3, Y0, Y0
	VPSHUFB Y5, Y0, Y0
	VPERMQ $216, Y0, Y0
	VPSHUFB Y4, Y2, Y2
	VMOVDQU ·vistrutahRoundConstants+16(SB), X6
	VPXOR Y2, Y0, Y0
	VPXOR Y6, Y0, Y0
	VAESENC Y1, Y0, Y0
	VAESENC Y3, Y0, Y0
	VPSHUFB Y5, Y0, Y0
	VPERMQ $216, Y0, Y0
	VPSHUFB Y4, Y2, Y2
	VMOVDQU ·vistrutahRoundConstants+32(SB), X6
	VPXOR Y2, Y0, Y0
	VPXOR Y6, Y0, Y0
	VAESENC Y1, Y0, Y0
	VAESENC Y3, Y0, Y0
	VPSHUFB Y5, Y0, Y0
	VPERMQ $216, Y0, Y0
	VPSHUFB Y4, Y2, Y2
	VMOVDQU ·vistrutahRoundConstants+48(SB), X6
	VPXOR Y2, Y0, Y0
	VPXOR Y6, Y0, Y0
	CMPQ CX, $10
	JE v256_blk_ymm_final
	VAESENC Y1, Y0, Y0
	VAESENC Y3, Y0, Y0
	VPSHUFB Y5, Y0, Y0
	VPERMQ $216, Y0, Y0
	VPSHUFB Y4, Y2, Y2
	VMOVDQU ·vistrutahRoundConstants+64(SB), X6
	VPXOR Y2, Y0, Y0
	VPXOR Y6, Y0, Y0
	VAESENC Y1, Y0, Y0
	VAESENC Y3, Y0, Y0
	VPSHUFB Y5, Y0, Y0
	VPERMQ $216, Y0, Y0
	VPSHUFB Y4, Y2, Y2
	VMOVDQU ·vistrutahRoundConstants+80(SB), X6
	VPXOR Y2, Y0, Y0
	VPXOR Y6, Y0, Y0
v256_blk_ymm_final:
	VAESENC Y1, Y0, Y0
	VPSHUFB Y4, Y2, Y2
	VAESENCLAST Y2, Y0, Y0
	VMOVDQU Y0, 0(DI)
	VPXOR X0, X0, X0
	VPXOR X1, X1, X1
	VPXOR X2, X2, X2
	VPXOR X3, X3, X3
	VPXOR X4, X4, X4
	VPXOR X5, X5, X5
	VPXOR X6, X6, X6
	XORQ DI, DI
	XORQ SI, SI
	XORQ DX, DX
	XORQ CX, CX
	VZEROUPPER
	RET

// func vistrutah256DecryptBlockYmmAsm(dst, src, key *[32]byte, rounds int)
TEXT ·vistrutah256DecryptBlockYmmAsm(SB),NOSPLIT,$0-32
